package com.receiptledger.v1.product;

import android.content.*;import android.database.*;import android.database.sqlite.*;import java.util.*;

public final class SqliteProductCatalogStore extends SQLiteOpenHelper implements ProductCatalogStore {
 public SqliteProductCatalogStore(Context c){super(c,ProductCatalogSchema.DB_NAME,null,ProductCatalogSchema.VERSION);}
 @Override public void onConfigure(SQLiteDatabase db){super.onConfigure(db);db.setForeignKeyConstraintsEnabled(true);}@Override public void onCreate(SQLiteDatabase db){db.execSQL(ProductCatalogSchema.CREATE_PRODUCTS);db.execSQL(ProductCatalogSchema.CREATE_ALIASES);db.execSQL(ProductCatalogSchema.CREATE_LINKS);db.execSQL(ProductCatalogSchema.CREATE_LINK_PRODUCT_INDEX);}@Override public void onUpgrade(SQLiteDatabase db,int oldV,int newV){throw new IllegalStateException("Explicit product catalog migration required: "+oldV+" -> "+newV);}
 public IdentityResolution confirm(String receiptId,int ordinal,String rawAlias,ProductType type,String canonicalName,long now){if(type==null||type==ProductType.UNCLASSIFIED)throw new IllegalArgumentException("classified type required");String ck=ProductNameNormalizer.key(canonicalName),ak=ProductNameNormalizer.key(rawAlias);if(ck.isEmpty()||ak.isEmpty())throw new IllegalArgumentException("name");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{CatalogProduct p=byCanonical(db,ck);if(p!=null&&p.type!=type)throw new IllegalStateException("canonical name already exists with different type");if(p==null){p=new CatalogProduct(UUID.randomUUID().toString(),type,canonicalName,now);ContentValues v=new ContentValues();v.put("id",p.id);v.put("type",p.type.name());v.put("canonical_name",p.canonicalName);v.put("canonical_key",p.canonicalKey);v.put("created_at_ms",p.createdAtMillis);db.insertOrThrow("products",null,v);}String existing=aliasProductId(db,ak);if(existing!=null&&!existing.equals(p.id))throw new IllegalStateException("alias already belongs to another product");if(existing==null){ContentValues a=new ContentValues();a.put("alias_key",ak);a.put("raw_alias",rawAlias);a.put("product_id",p.id);db.insertOrThrow("aliases",null,a);}writeLink(db,receiptId,ordinal,p.id,LinkSource.USER_CONFIRMED);db.setTransactionSuccessful();return IdentityResolution.linked(p,LinkSource.USER_CONFIRMED);}finally{db.endTransaction();}}
 public IdentityResolution resolveAndLinkExact(String receiptId,int ordinal,String rawAlias){SQLiteDatabase db=getWritableDatabase();String pid=aliasProductId(db,ProductNameNormalizer.key(rawAlias));if(pid==null)return IdentityResolution.unclassified();CatalogProduct p=byId(db,pid);if(p==null)return IdentityResolution.unclassified();writeLink(db,receiptId,ordinal,p.id,LinkSource.EXACT_ALIAS);return IdentityResolution.linked(p,LinkSource.EXACT_ALIAS);}
 public IdentityResolution itemResolution(String receiptId,int ordinal){SQLiteDatabase db=getReadableDatabase();try(Cursor c=db.query("item_links",new String[]{"product_id","link_source"},"receipt_id=? AND item_ordinal=?",new String[]{receiptId,Integer.toString(ordinal)},null,null,null)){if(!c.moveToFirst())return IdentityResolution.unclassified();CatalogProduct p=byId(db,c.getString(0));if(p==null)return IdentityResolution.unclassified();return IdentityResolution.linked(p,source(c.getString(1)));}}
 public CatalogProduct product(String id){return byId(getReadableDatabase(),id);}public List<CatalogProduct> listProducts(){List<CatalogProduct> out=new ArrayList<>();try(Cursor c=getReadableDatabase().query("products",null,null,null,null,null,"canonical_name COLLATE NOCASE ASC")){while(c.moveToNext())out.add(readProduct(c));}return Collections.unmodifiableList(out);}public List<ItemLinkRef> linksForProduct(String productId){List<ItemLinkRef> out=new ArrayList<>();try(Cursor c=getReadableDatabase().query("item_links",new String[]{"receipt_id","item_ordinal","link_source"},"product_id=?",new String[]{productId},null,null,"receipt_id ASC,item_ordinal ASC")){while(c.moveToNext())out.add(new ItemLinkRef(c.getString(0),c.getInt(1),productId,source(c.getString(2))));}return Collections.unmodifiableList(out);}
 public void unlinkItem(String receiptId,int ordinal){getWritableDatabase().delete("item_links","receipt_id=? AND item_ordinal=?",new String[]{receiptId,Integer.toString(ordinal)});}public void unlinkReceipt(String receiptId){getWritableDatabase().delete("item_links","receipt_id=?",new String[]{receiptId});}
 private static void writeLink(SQLiteDatabase db,String r,int o,String p,LinkSource s){ContentValues v=new ContentValues();v.put("receipt_id",r);v.put("item_ordinal",o);v.put("product_id",p);v.put("link_source",s.name());db.insertWithOnConflict("item_links",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 private static CatalogProduct byCanonical(SQLiteDatabase db,String key){try(Cursor c=db.query("products",null,"canonical_key=?",new String[]{key},null,null,null)){return c.moveToFirst()?readProduct(c):null;}}private static CatalogProduct byId(SQLiteDatabase db,String id){try(Cursor c=db.query("products",null,"id=?",new String[]{id},null,null,null)){return c.moveToFirst()?readProduct(c):null;}}private static String aliasProductId(SQLiteDatabase db,String key){if(key==null||key.isEmpty())return null;try(Cursor c=db.query("aliases",new String[]{"product_id"},"alias_key=?",new String[]{key},null,null,null)){return c.moveToFirst()?c.getString(0):null;}}
 private static CatalogProduct readProduct(Cursor c){ProductType t;try{t=ProductType.valueOf(c.getString(c.getColumnIndexOrThrow("type")));}catch(Exception e){t=ProductType.NON_STANDARD;}return new CatalogProduct(c.getString(c.getColumnIndexOrThrow("id")),t,c.getString(c.getColumnIndexOrThrow("canonical_name")),c.getLong(c.getColumnIndexOrThrow("created_at_ms")));}private static LinkSource source(String s){try{return LinkSource.valueOf(s);}catch(Exception e){return LinkSource.EXACT_ALIAS;}}
}
